const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Limpiar el + del teléfono para la API de WhatsApp
  const phone = (data.phone || '').replace(/^\+/, '');

  const meetLink = data.meet_link || 'Te llegó por correo';

  // Calcular tiempo restante hasta la cita
  // scheduled_date: "30-12-2025", scheduled_time: "13:00:00"
  const dateParts = data.scheduled_date.split('-');
  const day = parseInt(dateParts[0], 10);
  const month = parseInt(dateParts[1], 10) - 1; // Mes es 0-indexado
  const year = parseInt(dateParts[2], 10);

  const timeParts = data.scheduled_time.split(':');
  const hour = parseInt(timeParts[0], 10);
  const minute = parseInt(timeParts[1], 10);

  const appointmentDate = new Date(year, month, day, hour, minute, 0);
  const now = new Date();
  const diffMs = appointmentDate.getTime() - now.getTime();
  const diffMinutes = Math.floor(diffMs / 60000);

  // Debug info
  const debugInfo = {
    scheduled_date: data.scheduled_date,
    scheduled_time: data.scheduled_time,
    parsed: { year, month: month + 1, day, hour, minute },
    appointmentDate: appointmentDate.toISOString(),
    now: now.toISOString(),
    diffMs,
    diffMinutes
  };

  // Generar mensaje dinámico según tiempo restante
  let timeMessage = '';
  if (diffMinutes >= 115) {
    // Entre 1h 55min y 2h
    timeMessage = '⏰ *¡Tu cita es en casi 2 horas!*';
  } else if (diffMinutes >= 90) {
    // Entre 1h 30min y 1h 55min
    const hours = Math.floor(diffMinutes / 60);
    const mins = diffMinutes % 60;
    timeMessage = `⏰ *¡Tu cita es en ${hours} hora y ${mins} minutos!*`;
  } else if (diffMinutes >= 75) {
    // Entre 1h 15min y 1h 30min
    timeMessage = '⏰ *¡Tu cita es en 1 hora y media!*';
  } else if (diffMinutes >= 55) {
    // Entre 55min y 1h 15min (aproximadamente 1 hora)
    timeMessage = '⏰ *¡Tu cita es en 1 hora!*';
  } else if (diffMinutes >= 30) {
    // Entre 30min y 55min
    timeMessage = `⏰ *¡Tu cita es en ${diffMinutes} minutos!*`;
  } else if (diffMinutes > 0) {
    // Menos de 30 minutos
    timeMessage = '⏰ *¡Tu cita es en menos de 30 minutos!*';
  } else {
    // Ya pasó o es ahora
    timeMessage = '⏰ *¡Tu cita es AHORA!*';
  }

  const messageBody = {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: phone,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: {
        text: `${timeMessage}\n\nHola ${data.name}, te recordamos que tu reunión con AutomatizaTech está programada para hoy.\n\n📅 *Fecha:* ${data.scheduled_date}\n🕐 *Hora:* ${data.scheduled_time} hrs\n📍 *Enlace:* ${meetLink}\n\n¿Podrás asistir?`
      },
      action: {
        buttons: [
          {
            type: 'reply',
            reply: {
              id: `btn_reminder_confirm_${data.id}`,
              title: '✅ Sí, confirmo'
            }
          },
          {
            type: 'reply',
            reply: {
              id: `btn_reminder_no_${data.id}`,
              title: '❌ No podré'
            }
          }
        ]
      }
    }
  };

  results.push({
    json: {
      ...data,
      debugInfo: debugInfo,
      diffMinutes: diffMinutes,
      timeMessage: timeMessage,
      whatsappBody: JSON.stringify(messageBody)
    }
  });
}

return results;
